<template>
  <div><div v-if="error" class="error-banner"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><TeacherClassSelector v-if="auth.role !== 'student' && !selectedClassId" :classes="classes" :loading="loading" title="Tiến độ lớp học" description="Chọn một lớp để xem tiến độ bài học và hoạt động." feature-count-label="bài học" @select="selectClass" /><template v-else><div class="toolbar page-toolbar"><div v-if="auth.role !== 'student'" class="class-context"><strong>{{ selectedClassLabel }}</strong><button class="mini-button" @click="changeClass">Đổi lớp</button></div><select v-else v-model="selectedClassId" class="form-select" style="max-width:340px"><option value="">Chọn lớp học</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }}</option></select><div class="toolbar-actions"><span class="cell-subtle">{{ progressPercent }}% hoàn thành</span></div></div><div v-if="loading" class="loading-state">Đang tải tiến độ…</div><template v-else-if="courseProgress"><div class="metrics-grid"><MetricCard icon="✓" :label="auth.role === 'student' ? 'Bài học hoàn thành' : 'Số bài hoàn thành trung bình / sinh viên'" :value="`${completedLessons}/${totalLessons}`" :hint="auth.role === 'student' ? 'Tiến độ cá nhân' : 'Trung bình toàn lớp, có thể khác từng sinh viên'" /><MetricCard icon="↗" label="Tiến độ khóa học" :value="`${progressPercent}%`" hint="Dữ liệu tổng hợp hiện tại" /><MetricCard icon="▤" label="Hoạt động" :value="activityEntries.length" hint="Có trạng thái học tập" /><MetricCard icon="◷" label="Cập nhật" :value="formatDateTime(lastUpdated)" hint="Thời gian gần nhất" /></div><section class="panel"><div class="panel-heading"><h2>Tiến độ bài học</h2><span>{{ lessonEntries.length }} bản ghi</span></div><div v-if="lessonEntries.length" class="list-compact"><div v-for="entry in lessonEntries" :key="`${entry.studentId}-${entry.lessonId}`" class="list-compact-item"><div><strong>{{ entry.lessonTitle }}</strong><span>{{ enumLabel(entry.status, enumLabels.lessonProgressStatus) }} · {{ entry.updatedAt ? formatDateTime(entry.updatedAt) : 'Chưa bắt đầu' }}</span></div><StatusPill :value="entry.status" :labels="enumLabels.lessonProgressStatus" /></div></div><div v-else class="empty-state"><strong>Chưa có dữ liệu bài học</strong><span>Tiến độ sẽ được ghi nhận khi người học mở và hoàn thành bài.</span></div></section><section class="panel"><div class="panel-heading"><h2>Tiến độ hoạt động</h2><span>{{ activityEntries.length }} hoạt động</span></div><div v-if="activityEntries.length" class="list-compact"><div v-for="entry in activityEntries" :key="`${entry.studentId}-${entry.activityId}`" class="list-compact-item"><div><strong>{{ entry.activityTitle }}</strong><span>{{ entry.score }}/{{ entry.maxScore }} · {{ entry.completion }}%</span></div><StatusPill :value="entry.status" :labels="enumLabels.learningProgressStatus" /></div></div><div v-else class="empty-state"><strong>Chưa có tiến độ hoạt động</strong><span>Hoạt động hoàn thành sẽ hiển thị tại đây.</span></div></section></template><div v-else class="panel empty-state"><strong>Chưa có dữ liệu tiến độ</strong><span>Chọn lớp để tải dữ liệu tiến độ.</span></div></template></div>
</template>
<script setup lang="ts">
import { errorMessage } from '../../../shared/api/http'
import { computed, onMounted, ref, watch } from 'vue'; import MetricCard from '../../../shared/ui/MetricCard.vue'; import StatusPill from '../../../shared/ui/StatusPill.vue'; import TeacherClassSelector from '../../../shared/ui/TeacherClassSelector.vue'; import { academicsApi, learningApi } from '../../../shared/api/client'; import { enumLabels, enumLabel, formatDateTime, type LearningClass } from '../../../shared/types'; import { useAuthStore } from '../../../shared/stores/auth'
type LessonEntry = { studentId: string; lessonId: string; lessonTitle: string; status?: string | number; updatedAt?: string }; type ActivityEntry = { studentId: string; activityId: string; activityTitle: string; score: number; maxScore: number; completion: number; status?: string | number; completedAt?: string }
const auth = useAuthStore(); const classes = ref<LearningClass[]>([]); const selectedClassId = ref(''); const courseProgress = ref<{ totalLessons?: number; completedLessons?: number; entries?: LessonEntry[]; completionPercent?: number } | null>(null); const loading = ref(true); const error = ref(''); const lessonEntries = computed(() => courseProgress.value?.entries || []); const activityEntries = ref<ActivityEntry[]>([]); const selectedClassLabel = computed(() => { const item = classes.value.find(entry => entry.id === selectedClassId.value); return item ? `${item.code} · ${item.name}` : 'Lớp học' }); const totalLessons = computed(() => Number(courseProgress.value?.totalLessons ?? lessonEntries.value.length)); const progressPercent = computed(() => Math.round(Number(courseProgress.value?.completionPercent ?? 0))); const completedLessons = computed(() => Number(courseProgress.value?.completedLessons ?? Math.round(totalLessons.value * progressPercent.value / 100))); const lastUpdated = computed(() => lessonEntries.value.map(item => item.updatedAt).filter(Boolean).sort().at(-1)); function selectClass(id: string) { selectedClassId.value = id }; function changeClass() { selectedClassId.value = '' }
async function load() { if (!selectedClassId.value) { courseProgress.value = null; loading.value = false; return }; loading.value = true; try { const result = await learningApi.courseProgress(selectedClassId.value, auth.role === 'student'); courseProgress.value = result as typeof courseProgress.value; const own = auth.role === 'student' ? await learningApi.myProgress(selectedClassId.value) : await learningApi.classProgress(selectedClassId.value); activityEntries.value = (own.entries || []) as ActivityEntry[] } catch (cause) { error.value = errorMessage(cause) || 'Không tải được tiến độ.' } finally { loading.value = false } }
async function boot() { try { classes.value = await academicsApi.classes(); if (auth.role === 'student' && classes.value[0]) selectedClassId.value = classes.value[0].id; else loading.value = false } catch (cause) { error.value = errorMessage(cause) || 'Không tải được lớp học.'; loading.value = false } }; watch(selectedClassId, load); onMounted(boot)
</script>
